exports.shorthands = undefined;

// Global, collision-proof user system IDs.
//
// Old scheme: per-school "TCH-000N" / "STU-000N", generated by reading the
// current max and adding one — which raced on the first row per school and
// broke past 9999 (lexical sort). "TCH-0001" also existed in every school, so
// login-by-ID (which carries no school context) matched an arbitrary person.
//
// New scheme (shared/system-id.ts): <T|S><YY><seq>, e.g. T260001 / S260042.
//   T / S  staff or student
//   YY     last two digits of the year the account was created, frozen for life
//   seq    a per-(type, year) counter allocated across the WHOLE platform via
//          id_sequence — one atomic upsert per ID, no race, no read-max.
// The full ID is globally unique, so a single unique index enforces it and
// login-by-ID is unambiguous.
//
// This migration also REWRITES every existing student/teacher system_id into
// the new scheme (ordered by created_at, so the oldest account keeps the
// lowest number). Only `student` and `teacher` roles ever had a system_id;
// school-admins, parents and super-admins have none and are untouched.
// NOTE: anyone who logs in with their system ID must use the new value
// afterwards — communicate the change before running this against real users.

exports.up = (pgm) => {
  pgm.createTable("id_sequence", {
    scope: { type: "text", primaryKey: true },
    next_value: { type: "bigint", notNull: true },
  });

  // Rewrite existing IDs and seed id_sequence from the highest number issued
  // per scope, in one statement. `ranked` reads the pre-statement snapshot;
  // `renamed` writes from it; the final INSERT reads the same `ranked`.
  pgm.sql(`
    with ranked as (
      select
        u.id,
        case when u.role = 'student' then 'S' else 'T' end                    as p,
        to_char(u.created_at at time zone 'UTC', 'YYYY')                       as yyyy,
        to_char(u.created_at at time zone 'UTC', 'YY')                         as yy,
        row_number() over (
          partition by case when u.role = 'student' then 'S' else 'T' end,
                       to_char(u.created_at at time zone 'UTC', 'YYYY')
          order by u.created_at, u.id
        )                                                                     as seq
      from users u
      where u.role in ('student', 'teacher') and u.system_id is not null
    ),
    renamed as (
      update users u
         set system_id = r.p || r.yy || lpad(r.seq::text, 4, '0'),
             updated_at = now()
        from ranked r
       where u.id = r.id
      returning 1
    )
    insert into id_sequence (scope, next_value)
    select p || ':' || yyyy, max(seq)
      from ranked
     group by p, yyyy
  `);

  // Every system_id is now the new format and globally unique — enforce it,
  // and retire the now-redundant per-school index.
  pgm.sql(`drop index if exists users_school_id_system_id_unique_index`);
  pgm.sql(`
    create unique index users_system_id_unique
      on users (system_id)
      where system_id is not null
  `);
};

exports.down = (pgm) => {
  pgm.sql(`drop index if exists users_system_id_unique`);
  pgm.sql(`
    create unique index users_school_id_system_id_unique_index
      on users (school_id, system_id)
      where system_id is not null
  `);
  pgm.dropTable("id_sequence");
  // The rewritten system_id values are not restored.
};
